// restrict which attribute keys are retained for an instrument. See
// go.opentelemetry.io/otel/metric/x.WithDefaultAttributes.
type allowKeysOption interface {
	AllowedKeys() []attribute.Key
}

// allowedAttributeKeys returns the attribute keys allowed by options. If no
// option specifies allowed keys, nil is returned and no attribute filtering
// should be applied. If multiple options specify allowed keys, the last one
// takes precedence.
func allowedAttributeKeys[O any](options []O) []attribute.Key {
	var keys []attribute.Key
	for _, o := range options {
		if a, ok := any(o).(allowKeysOption); ok {
			keys = a.AllowedKeys()
		}
	}
	return keys
}

