// Package x contains support for OpenTelemetry metric SDK experimental
// features.
//
// This package should only be used for features defined in the specification.
// It should not be used for experiments or new project ideas.
package x // import "go.opentelemetry.io/otel/metric/x"

import (
	"slices"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/metric"
)

// WithDefaultAttributes returns a [metric.InstrumentOption] that specifies the
// attribute keys that are allowed by default for the metric instrument being
// created.
//
// When the returned option is passed during instrument creation, only the
// attributes whose keys appear in keys are retained in recorded data points;
// all other attributes are filtered out.
//
// If keys is empty, all attributes are filtered out and recorded data points
// will contain an empty attribute set.
//
// If this option is not passed during instrument creation, no attribute
// filtering is applied and all recorded attributes are retained.
//
// A view that explicitly matches the instrument takes precedence over this
// option. When such a view matches, the view's attribute configuration is used
// and this option is ignored.
//
// This is an experimental feature and may be removed or changed in a backwards
// incompatible way in a future release.
func WithDefaultAttributes(keys ...attribute.Key) metric.InstrumentOption {
	return defaultAttributesOption{keys: slices.Clone(keys)}
}

// defaultAttributesOption is a [metric.InstrumentOption] that restricts the
// attribute keys retained for an instrument to a provided allow-list.
//
// It embeds [metric.InstrumentOption] so that it satisfies that interface (and
// all the instrument option interfaces it embeds) without implementing the
// unexported methods of the metric package. It implements Experimental so the
// standard configuration constructors skip it, ensuring the embedded nil
// option is never used.
type defaultAttributesOption struct {
	metric.InstrumentOption

	keys []attribute.Key
}

// Experimental marks the option as experimental so it is ignored by the
// standard metric configuration constructors, preventing a panic from the
// embedded nil [metric.InstrumentOption].
func (defaultAttributesOption) Experimental() {}

// AllowedKeys returns the attribute keys allowed for the instrument.
//
// A non-nil (possibly empty) slice is always returned so callers can
// distinguish "the option was provided with no keys" (filter everything) from
// "the option was not provided" (a nil slice, no filtering).
func (o defaultAttributesOption) AllowedKeys() []attribute.Key {
	if o.keys == nil {
		return []attribute.Key{}
	}
	return o.keys
}
