//
// A nil return means no such option was provided and no attribute filtering
// should be applied. A non-nil (possibly empty) return means filtering should
// be applied, allowing only the returned keys.
func defaultAttributes[T any](opts []T) []attribute.Key {
	var keys []attribute.Key
	var found bool
	for _, o := range opts {
		if exp, ok := any(o).(interface{ AllowedKeys() []attribute.Key }); ok {
