func attrsOf(t *testing.T, rm metricdata.ResourceMetrics) attribute.Set {
	t.Helper()
	sm := rm.ScopeMetrics[0].Metrics[0].Data.(metricdata.Sum[int64])
	return sm.DataPoints[0].Attributes
}

func TestVerifyWithDefaultAttributes(t *testing.T) {
	ctx := context.Background()
	full := attribute.NewSet(attribute.String("a", "1"), attribute.String("b", "2"))

	// Case 1: allow only key "a".
	rdr := NewManualReader()
	mp := NewMeterProvider(WithReader(rdr))
	c, err := mp.Meter("m").Int64Counter("c", x.WithDefaultAttributes(attribute.Key("a")))
	if err != nil {
		t.Fatal(err)
	}
	c.Add(ctx, 1, metricapiWith(full))
	var rm metricdata.ResourceMetrics
	if err := rdr.Collect(ctx, &rm); err != nil {
		t.Fatal(err)
	}
	if got := attrsOf(t, rm); got.Len() != 1 {
		t.Fatalf("case1: expected 1 attr, got %v", got.ToSlice())
	}

	// Case 2: empty keys -> all filtered out.
	rdr2 := NewManualReader()
	mp2 := NewMeterProvider(WithReader(rdr2))
	c2, _ := mp2.Meter("m").Int64Counter("c", x.WithDefaultAttributes())
	c2.Add(ctx, 1, metricapiWith(full))
	var rm2 metricdata.ResourceMetrics
	_ = rdr2.Collect(ctx, &rm2)
	if got := attrsOf(t, rm2); got.Len() != 0 {
		t.Fatalf("case2: expected 0 attrs, got %v", got.ToSlice())
	}

	// Case 3: no option -> all retained.
	rdr3 := NewManualReader()
	mp3 := NewMeterProvider(WithReader(rdr3))
	c3, _ := mp3.Meter("m").Int64Counter("c")
	c3.Add(ctx, 1, metricapiWith(full))
	var rm3 metricdata.ResourceMetrics
	_ = rdr3.Collect(ctx, &rm3)
	if got := attrsOf(t, rm3); got.Len() != 2 {
		t.Fatalf("case3: expected 2 attrs, got %v", got.ToSlice())
	}

	// Case 4: view matching all instruments overrides the filter.
	rdr4 := NewManualReader()
	mp4 := NewMeterProvider(WithReader(rdr4), WithView(func(i Instrument) (Stream, bool) {
		return Stream{Name: i.Name, Description: i.Description, Unit: i.Unit}, true
	}))
	c4, _ := mp4.Meter("m").Int64Counter("c", x.WithDefaultAttributes(attribute.Key("a")))
	c4.Add(ctx, 1, metricapiWith(full))
	var rm4 metricdata.ResourceMetrics
	_ = rdr4.Collect(ctx, &rm4)
	if got := attrsOf(t, rm4); got.Len() != 2 {
		t.Fatalf("case4: view should override filter, expected 2 attrs, got %v", got.ToSlice())
	}
}
